using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Windows.Controls;
using System.Windows;

namespace QiDesk {
public static class AiSettings {
    static readonly string[] stateKeys={"Page","Pages","AutoRules","HideOriginalIcons","HideDesktopIcons","PushIconsAside","DoubleClickHide","DesktopDragCreate","RollupEnabled","RollupOnDoubleClick","HoverExpand","EdgeRollup","PortalNavigate","SnapEnabled","SnapGrid","SnapGap","AutoDailySnapshot","SnapshotKeepDays","LayoutMode","IdleHideSeconds","AutoShowOnDesktop","QuickSearchAll","ShowFileExtensions","PetVisible","PetScale","PetSkin","AiEndpoint","AiModel","McpEnabled","WorkAutoIgnore","WorkIgnoreCaches","AutoImportIgnoreFiles","AutoDetectWorkspaces","ScreenshotFolder","UseEverything","EverythingPath"};
    static readonly string[] groupKeys={"Name","Color","Page","X","Y","Width","Height","Opacity","BackgroundOpacity","TintStrength","Rolled","Locked","ExcludeFromHide","Sort","SortDescending","TitleMode","LabelColor","LabelSize","LabelFont","IconSize","ViewMode","IconSkin","IconColor"};
    static readonly string[] widgetKeys=groupKeys.Except(new[]{"IconSkin","IconColor"}).Concat(new[]{"ShowSeconds","TimeZone","Text","TargetDate","ShowLunar","ShowCalendarClock","WeekStartMonday"}).ToArray();
    static Dictionary<string,object> Values(object target,string[] keys){return keys.ToDictionary(k=>k,k=>target.GetType().GetProperty(k).GetValue(target,null));}
    public static object Get(Store store){return new {settings=Values(store.Data,stateKeys),groups=store.Data.Groups.Select(g=>new {id=g.Id,settings=Values(g,groupKeys)}).ToArray(),widgets=store.Data.Widgets.Select(w=>new {id=w.Id,pluginId=w.PluginId,settings=Values(w,widgetKeys)}).ToArray(),rules=store.Data.Rules,plugins=WidgetPlugins.All(store.Data).Select(p=>new {id=p.Id,name=p.Name,enabled=p.Enabled,kind=p.Kind}).ToArray()};}
    static void Assign(object target,Dictionary<string,object> changes,string[] keys){if(changes.Count==0)throw new Exception("settings cannot be empty.");foreach(var pair in changes){if(!keys.Contains(pair.Key))throw new Exception("Unsupported setting: "+pair.Key);var prop=target.GetType().GetProperty(pair.Key);object value=pair.Value;Type type=prop.PropertyType;if(type==typeof(bool)){if(!(value is bool))throw new Exception(pair.Key+" must be boolean.");}else if(type==typeof(string)){if(!(value is string)||((string)value).Length>2000)throw new Exception(pair.Key+" must be a string.");ValidateText(pair.Key,(string)value);}else{if(value==null||value is string||value is bool)throw new Exception(pair.Key+" must be a number.");double n=Convert.ToDouble(value);double min=0,max=20000;if(pair.Key=="Pages"){min=1;max=20;}else if(pair.Key=="Page")max=19;else if(pair.Key=="Width"){min=220;max=2000;}else if(pair.Key=="Height"){min=100;max=2000;}else if(pair.Key=="X"||pair.Key=="Y")min=-20000;else if(pair.Key=="IconSize"){min=20;max=96;}else if(pair.Key=="LabelSize"){min=10;max=24;}else if(pair.Key=="Opacity"){min=.3;max=1;}else if(pair.Key=="TintStrength"||pair.Key=="BackgroundOpacity")max=1;else if(pair.Key=="PetScale"){min=.5;max=2;}else if(pair.Key=="SnapGrid"){min=1;max=64;}else if(pair.Key=="SnapGap")max=80;else if(pair.Key=="SnapshotKeepDays"){min=1;max=30;}else if(pair.Key=="IdleHideSeconds")max=3600;if(Double.IsNaN(n)||Double.IsInfinity(n)||n<min||n>max||(type==typeof(int)&&Math.Truncate(n)!=n))throw new Exception("Out of range: "+pair.Key);value=type==typeof(int)?(object)Convert.ToInt32(n):n;}prop.SetValue(target,value,null);}}
    static void ValidateText(string key,string value){string[] values=null;if(key=="Color"||key=="LabelColor"||key=="IconColor")try{System.Windows.Media.ColorConverter.ConvertFromString(value);}catch{throw new Exception("Invalid color.");}if(key=="Name"&&(String.IsNullOrWhiteSpace(value)||value.Length>80))throw new Exception("Name must be 1 to 80 characters.");if(key=="IconSkin")values=AppIconSkins.Choices;if(key=="PetSkin")values=DesktopPet.Skins;if(key=="ViewMode")values=new[]{"图标","列表","详细信息"};if(key=="TitleMode")values=new[]{"总是","从不","鼠标悬停"};if(key=="Sort")values=new[]{"名称","类型","修改时间","大小"};if(key=="LayoutMode")values=new[]{"保持位置","按显示器恢复","按工作区缩放"};if(values!=null&&!values.Contains(value))throw new Exception("Invalid option: "+key);if(key=="TimeZone"&&value!="local")TimeZoneInfo.FindSystemTimeZoneById(value);if(key=="TargetDate"&&value.Length>0){DateTime date;if(!DateTime.TryParse(value,out date))throw new Exception("Invalid target date.");}if(key=="ScreenshotFolder"&&value.Length>0&&!WorkspaceConnections.SafeDirectory(value))throw new Exception("Screenshot folder must be an existing local folder.");if(key=="EverythingPath"&&value.Length>0&&(!File.Exists(value)||!Path.GetFileName(value).Equals("everything.exe",StringComparison.OrdinalIgnoreCase)))throw new Exception("Select an existing Everything.exe.");if(key=="AiEndpoint"){Uri uri;if(!Uri.TryCreate(value,UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https"))throw new Exception("AI endpoint must be HTTP or HTTPS.");}}
    public static bool Apply(Controller c,string name,Dictionary<string,object> args,out object result){result=null;if(name=="qidesk_update_settings"||name=="qidesk_update_group"||name=="qidesk_update_widget"){object changes;var settings=args.TryGetValue("settings",out changes)?changes as Dictionary<string,object>:null;if(settings==null)throw new Exception("settings must be an object.");object target=c.Store.Data;string[] keys=stateKeys;if(name=="qidesk_update_group"){string id=Convert.ToString(args["groupId"]);target=c.Store.Data.Groups.FirstOrDefault(g=>g.Id==id);keys=groupKeys;}if(name=="qidesk_update_widget"){string id=Convert.ToString(args["widgetId"]);target=c.Store.Data.Widgets.FirstOrDefault(g=>g.Id==id);keys=widgetKeys;}if(target==null)throw new Exception("Unknown group or widget.");Assign(target,settings,keys);if(c.Store.Data.Page>=c.Store.Data.Pages||c.Store.Data.Groups.Any(g=>g.Page>=c.Store.Data.Pages)||c.Store.Data.Widgets.Any(g=>g.Page>=c.Store.Data.Pages))throw new Exception("Page must be smaller than Pages (zero based).");result=new {updated=settings.Keys.ToArray(),undoAvailable=true};return true;}if(name=="qidesk_set_rules"){var rules=Store.Json.Deserialize<List<Rule>>(Convert.ToString(args["rulesJson"]));if(rules==null||rules.Count>100)throw new Exception("Provide at most 100 rules.");foreach(var r in rules)if(r==null||!c.Store.Data.Groups.Any(g=>g.Id==r.GroupId&&String.IsNullOrEmpty(g.Folder))||r.Name.Length>80||r.Contains.Length>240||r.Extensions.Length>240||!new[]{"包含","开头","结尾"}.Contains(r.NameMode)||!new[]{"全部","文件","文件夹"}.Contains(r.Kind))throw new Exception("Invalid rule target or condition.");c.Store.Data.Rules=rules;result=new {updated=rules.Count};return true;}if(name=="qidesk_remove_widget"){string id=Convert.ToString(args["widgetId"]);if(c.Store.Data.Widgets.RemoveAll(w=>w.Id==id)==0)throw new Exception("Unknown widget.");result=new {removed=true};return true;}return false;}
    static Dictionary<string,object> SettingsSchema(Type type,string[] keys){var properties=new Dictionary<string,object>();foreach(string key in keys){Type t=type.GetProperty(key).PropertyType;properties[key]=new Dictionary<string,object>{{"type",t==typeof(bool)?"boolean":t==typeof(string)?"string":t==typeof(int)?"integer":"number"}};}return new Dictionary<string,object>{{"type","object"},{"properties",properties},{"additionalProperties",false},{"minProperties",1}};}
    static object Tool(string name,string description,bool readOnly,string id,Type type=null,string[] keys=null){var props=new Dictionary<string,object>();if(id.Length>0)props[id]=new Dictionary<string,object>{{"type","string"}};if(type!=null)props["settings"]=SettingsSchema(type,keys);string[] required=(id.Length>0?new[]{id}:new string[0]).Concat(type==null?new string[0]:new[]{"settings"}).ToArray();return new Dictionary<string,object>{{"name",name},{"description",description},{"inputSchema",new Dictionary<string,object>{{"type","object"},{"properties",props},{"required",required},{"additionalProperties",false}}},{"annotations",new {readOnlyHint=readOnly,destructiveHint=false,openWorldHint=false}}};}
    public static object[] Tools(){var search=(Dictionary<string,object>)Tool("qidesk_search_files","Query Everything file metadata. Does not read file contents. Query supports Everything syntax; UI fallback only matches names.",true,"query");var props=(Dictionary<string,object>)((Dictionary<string,object>)search["inputSchema"])["properties"];props["mode"]=new Dictionary<string,object>{{"type","string"},{"enum",new[]{"search","modified"}}};return new[]{Tool("qidesk_get_settings","Read all global, group and widget settings, plus rules. Page indexes are zero based.",true,""),Tool("qidesk_update_settings","Change global settings. Validated, persisted and undoable.",false,"",typeof(State),stateKeys),Tool("qidesk_update_group","Change group appearance, view, sorting and layout. Page is zero based.",false,"groupId",typeof(Group),groupKeys),Tool("qidesk_update_widget","Change widget appearance, text, date, timezone and layout.",false,"widgetId",typeof(DesktopWidget),widgetKeys),Tool("qidesk_remove_widget","Remove a desktop widget instance. Does not delete files.",false,"widgetId"),Tool("qidesk_set_rules","Replace ordered organizing rules with a JSON array of Rule objects. Valid group targets required.",false,"rulesJson")};}
}
public partial class ManagerWindow {
    public void ShowQuickSort(Group group,Window owner){var menu=new ContextMenu();foreach(string option in new[]{"名称","类型","修改时间","大小"}){string kind=option;var item=Ui.Menu(kind,delegate{controller.Store.Checkpoint();group.Sort=kind;group.SortDescending=kind=="修改时间"||kind=="大小";controller.SaveAndRefresh(false);});item.IsChecked=group.Sort==kind;menu.Items.Add(item);}menu.Items.Add(new Separator());foreach(bool descending in new[]{false,true}){bool direction=descending;var item=Ui.Menu(descending?"降序":"升序",delegate{controller.Store.Checkpoint();group.SortDescending=direction;controller.SaveAndRefresh(false);});item.IsChecked=group.SortDescending==direction;menu.Items.Add(item);}menu.PlacementTarget=owner;menu.IsOpen=true;}
}
}
